def f(g,bgc):
    out=[r[:] for r in g]; H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]
    def comps(col, s=seen):
        res=[]
        for i in range(H):
            for j in range(W):
                if g[i][j]==col and not s[i][j]:
                    st=[(i,j)]; s[i][j]=True; cs=[]
                    while st:
                        x,y=st.pop(); cs.append((x,y))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and g[a][b]==col and not s[a][b]:
                                s[a][b]=True; st.append((a,b))
                    res.append(cs)
        return res
    colors=set(x for r in g for x in r)-{bgc}
    for col in colors:
        for cs in comps(col):
            rs=[p[0] for p in cs]; cc=[p[1] for p in cs]
            r0,r1,c0,c1=min(rs),max(rs),min(cc),max(cc)
            cells={(x,y) for x,y in cs}
            h_,w_=r1-r0+1,c1-c0+1
            full=h_*w_==len(cells)
            bordercells=2*h_+2*w_-4
            if not full and len(cells)>0 and h_>1 and w_>1 and len(cells)==bordercells:
                fill = 7 if h_%2!=0 else 2
                for x in range(r0,r1+1):
                    for y in range(c0,c1+1):
                        if g[x][y]==bgc: out[x][y]=fill
    return out
